    @SafeVarargs
    static <T> List<T> listOf(T... items) {
        return List.of(items);
    }

    static Set<TokenType> tokens(TokenType... items) {
        if (items.length == 0) {
            return Set.of();
        }
        EnumSet<TokenType> s = EnumSet.noneOf(TokenType.class);
        java.util.Collections.addAll(s, items);
        return java.util.Collections.unmodifiableSet(s);
    }

    static Set<DType> dtypes(DType... items) {
        if (items.length == 0) {
            return Set.of();
        }
        EnumSet<DType> s = EnumSet.noneOf(DType.class);
        java.util.Collections.addAll(s, items);
        return java.util.Collections.unmodifiableSet(s);
    }

    static Set<ExprType> types(ExprType... items) {
        if (items.length == 0) {
            return Set.of();
        }
        EnumSet<ExprType> s = EnumSet.noneOf(ExprType.class);
        java.util.Collections.addAll(s, items);
        return java.util.Collections.unmodifiableSet(s);
    }

    static Set<String> strings(String... items) {
        return java.util.Collections.unmodifiableSet(new java.util.LinkedHashSet<>(java.util.Arrays.asList(items)));
    }

    @SuppressWarnings("unchecked")
    static <K, V> Map<K, V> map(Object... kv) {
        Map<K, V> m;
        if (kv.length > 0 && kv[0] instanceof Enum<?> e) {
            m = new java.util.EnumMap(e.getDeclaringClass());
        } else {
            m = new java.util.LinkedHashMap<>();
        }
        for (int i = 0; i < kv.length; i += 2) {
            m.put((K) kv[i], (V) kv[i + 1]);
        }
        return java.util.Collections.unmodifiableMap(m);
    }

    @SuppressWarnings("unchecked")
    static Map<String, List<List<String>>> options(Object... kv) {
        Map<String, List<List<String>>> m = new java.util.LinkedHashMap<>();
        for (int i = 0; i < kv.length; i += 2) {
            m.put((String) kv[i], (List<List<String>>) kv[i + 1]);
        }
        return java.util.Collections.unmodifiableMap(m);
    }

